<div class="grid gap-5 rounded-xl border border-slate-200 bg-white p-6 shadow-sm md:grid-cols-2"><label class="text-sm font-semibold">Requisition Date<input name="requisition_date" type="date" value="{{ old('requisition_date', now()->format('Y-m-d')) }}" class="mt-2 block w-full rounded border-slate-300"></label><label class="text-sm font-semibold">Requisition No<input readonly value="{{ $nextNo }}" class="mt-2 block w-full rounded border-slate-200 bg-slate-100"></label><label class="text-sm font-semibold md:col-span-2">Remarks<input name="remarks" value="{{ old('remarks') }}" class="mt-2 block w-full rounded border-slate-300"></label></div>
