<script>function requisitionForm(){return{products:@json($products),lines:[{partNo:'',productId:'',name:'',qty:0}],add(){this.lines.push({partNo:'',productId:'',name:'',qty:0})},remove(i){this.lines.splice(i,1)},match(line){let q=line.partNo.toLowerCase();let product=this.products.find(p=>p.part_no?.toLowerCase()===q||`${p.part_no} — ${p.name}`.toLowerCase()===q);if(product){line.productId=product.id;line.partNo=product.part_no;line.name=product.name}else{line.productId='';line.name=''}}}}</script>
